import {expect,it} from 'vitest';
import {sipCalculator,sipFutureValue,requiredMonthlySip} from '../finance/sip';
import {runCalculator} from '../engine';
import {sipInverseIndependentVectors} from './fixtures/sip-inverse-independent';
for(const vector of sipInverseIndependentVectors){
 it(`independent SIP inverse and signed result: ${vector.label}`,()=>{
  // Literal target and contribution derive from the rational annuity sum above;
  // not solely a forward/reverse round-trip generated by the same implementation.
  expect(requiredMonthlySip(vector.target,vector.annualReturnPercent,vector.termMonths,vector.timing)).toBeCloseTo(vector.monthly,10);
  expect(sipFutureValue(vector.monthly,vector.annualReturnPercent,vector.termMonths,vector.timing)).toBeCloseTo(vector.target,10);
  for(const plan of ['free','pro','business'])for(const context of [{locale:'en-US',currency:'USD'},{locale:'de-DE',currency:'EUR'}]){
   expect(runCalculator(sipCalculator,{monthlyContribution:vector.monthly,annualReturnPercent:vector.annualReturnPercent,termMonths:vector.termMonths,contributionTiming:vector.timing,plan},context).output).toEqual(vector.expected);
  }
 });
}
it('preserves small nonzero unrounded inverse values without claiming display reconciliation',()=>{
 // Two end contributions: .01 × (1 + .95) = .0195 before display rounding.
 expect(requiredMonthlySip(.0195,-60,2,'end')).toBeCloseTo(.01,14);
 // Two beginning contributions: .01 × (.95 + .9025) = .018525.
 expect(requiredMonthlySip(.018525,-60,2,'beginning')).toBeCloseTo(.01,14);
});
it('fails closed when a schema-allowed tiny modeled rate loses the annuity factor',()=>{
 expect(sipCalculator.inputSchema.safeParse({monthlyContribution:1,annualReturnPercent:1e-300,termMonths:1200,contributionTiming:'end'}).success).toBe(true);
 expect(()=>requiredMonthlySip(1,1e-300,1200,'end')).toThrow();
});
it('retains existing source, version and golden bindings',()=>{
 expect(sipCalculator.id).toBe('finance.sip');expect(sipCalculator.version).toBe(1);expect(sipCalculator.goldenTests).toHaveLength(6);
 expect(sipCalculator.sources.length).toBeGreaterThan(0);
});
